Certainly! Below is an example of improper use of the Java API that can lead to vulnerabilities in web applications, specifically SQL Injection. This is followed by a corrected version using prepared statements to mitigate the vulnerability.

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;

public class VulnerableExample {
    public static void main(String[] args) {
        String userInput = "1 OR 1=1"; // Simulated user input that is malicious
        Connection connection = null;
        Statement statement = null;
        ResultSet resultSet = null;

        try {
            // Establishing a connection to the database
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "user", "password");
            statement = connection.createStatement();

            // Vulnerable: Directly concatenating user input into the SQL query
            String query = "SELECT * FROM users WHERE id = " + userInput;
            resultSet = statement.executeQuery(query);

            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getInt("id"));
                System.out.println("Username: " + resultSet.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Closing resources
            try {
                if (resultSet != null) resultSet.close();
                if (statement != null) statement.close();
                if (connection != null) connection.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureExample {
    public static void main(String[] args) {
        String userInput = "1"; // Simulated user input
        Connection connection = null;
        PreparedStatement preparedStatement = null;
        ResultSet resultSet = null;

        try {
            // Establishing a connection to the database
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "user", "password");

            // Secure: Using a prepared statement to prevent SQL Injection
            String query = "SELECT * FROM users WHERE id = ?";
            preparedStatement = connection.prepareStatement(query);
            preparedStatement.setInt(1, Integer.parseInt(userInput)); // Safely setting the user input

            resultSet = preparedStatement.executeQuery();

            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getInt("id"));
                System.out.println("Username: " + resultSet.getString("username"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Closing resources
            try {
                if (resultSet != null) resultSet.close();
                if (preparedStatement != null) preparedStatement.close();
                if (connection != null) connection.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

In the first snippet, the code is vulnerable to SQL Injection because it directly concatenates user input into the SQL query. The second snippet fixes this issue by using a `PreparedStatement`, which safely handles user input and prevents SQL Injection attacks.

