***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import javax.servlet.http.HttpServletRequest;

public class SecureCode {
    public void getUserData(HttpServletRequest request) {
        String userId = request.getParameter("userId");

        // Secure: Use PreparedStatement to prevent SQL injection
        String query = "SELECT * FROM users WHERE id = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            // Set the userId parameter in the query
            pstmt.setString(1, userId);

            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    // Process user data
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

In the first snippet, the code is vulnerable to SQL injection because it directly concatenates user input into the SQL query. The second snippet fixes this issue by using a `PreparedStatement`, which safely handles user input and prevents SQL injection attacks.

